'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');
const { toObjects } = require('./src/rows');

function stream(chunks, options) {
  const parser = createParser(options);
  const records = [];
  for (const chunk of chunks) records.push(...parser.push(chunk));
  records.push(...parser.end());
  assert.deepEqual(parser.end(), []);
  assert.throws(() => parser.push(''), Error);
  return records;
}

test('grammar is independent of chunk boundaries', () => {
  const cases = [
    ['', []], ['\uFEFF', []], ['\n', [['']]], ['\n\n', [[''], ['']]],
    ['\r\n', [['']]], ['\r\r\n\n', [[''], [''], ['']]],
    ['a\r\nb\rc\nd', [['a'], ['b'], ['c'], ['d']]],
    [',,', [['', '', '']]], ['a,\n', [['a', '']]],
    ['""', [['']]], ['""""', [['"']]], ['"a""b",c', [['a"b', 'c']]],
    ['a"b,"c,d"', [['a"b', 'c,d']]],
    ['"a\r\nb\rc\nd",tail\r\n', [['a\r\nb\rc\nd', 'tail']]],
    ['\uFEFF"a",\uFEFFb\n\uFEFF', [['a', '\uFEFFb'], ['\uFEFF']]],
    ['"😀",😀', [['😀', '😀']]],
    ['a;"b;c";', [['a', 'b;c', '']], { delimiter: ';' }],
    ['a\tb', [['a', 'b']], { delimiter: '\t' }],
    ['a\uD800b', [['a', 'b']], { delimiter: '\uD800' }],
    ['\uFEFFa\uFEFFb', [['a', 'b']], { delimiter: '\uFEFF' }],
  ];
  for (const [text, expected, options] of cases) {
    assert.deepEqual(parse(text, options), expected);
    assert.deepEqual(stream(text.split(''), options), expected);
    for (let cut = 0; cut <= text.length; cut++) {
      assert.deepEqual(stream(['', text.slice(0, cut), '', text.slice(cut), ''], options), expected);
    }
  }
});

test('all partitions of escaped quotes and CRLF', () => {
  const text = '"a""b"\r\nx';
  for (let mask = 0; mask < 2 ** (text.length - 1); mask++) {
    const chunks = [];
    let start = 0;
    for (let i = 1; i < text.length; i++) {
      if (mask & (1 << (i - 1))) {
        chunks.push(text.slice(start, i), '');
        start = i;
      }
    }
    chunks.push(text.slice(start));
    assert.deepEqual(stream(chunks), [['a"b'], ['x']]);
  }
});

test('completed rows are emitted immediately and never repeated', () => {
  const parser = createParser({ header: true });
  assert.deepEqual(parser.push(''), []);
  assert.deepEqual(parser.push('\uFEFFa\r'), [['a']]);
  assert.deepEqual(parser.push(''), []);
  assert.deepEqual(parser.push('\nb\n\r'), [['b'], ['']]);
  assert.deepEqual(parser.push('\n"x\r'), []);
  assert.deepEqual(parser.push('\ny"'), []);
  assert.deepEqual(parser.push('\r'), [['x\r\ny']]);
  assert.deepEqual(parser.end(), []);
  const left = createParser();
  const right = createParser();
  assert.deepEqual(left.push('a,'), []);
  assert.deepEqual(right.push('b\n'), [['b']]);
  assert.deepEqual(left.end(), [['a', '']]);
  assert.deepEqual(right.end(), []);
});

test('validation and physical error lines survive arbitrary splits', () => {
  for (const delimiter of [null, false, 1, '', 'ab', '😀', '"', '\r', '\n']) {
    assert.throws(() => createParser({ delimiter }), RangeError);
    assert.throws(() => parse('', { delimiter }), RangeError);
  }
  assert.deepEqual(parse('a,b', { delimiter: undefined }), [['a', 'b']]);
  const parser = createParser();
  for (const chunk of [null, undefined, 1, {}, [], Buffer.from('a'), new String('a')]) {
    assert.throws(() => parser.push(chunk), TypeError);
  }
  assert.deepEqual(parser.push('a'), []);
  assert.deepEqual(parser.end(), [['a']]);
  assert.deepEqual(parser.end(), []);
  assert.throws(() => parser.push('a'), Error);
  const errors = [
    ['"a"x', 1, false], ['"a" ', 1, false],
    ['a\r\n"b"x', 2, false], ['a\r"b"x', 2, false],
    ['"a\r\nb\rc\nd" x', 4, false],
    ['"', 1, true], ['"a\r\n', 2, true], ['"a\r\n\r\n', 3, true],
    ['x\n"a\rb\nc', 4, true], ['"a""', 1, true],
  ];
  for (const [text, line, atEnd] of errors) {
    for (let cut = 0; cut <= text.length; cut++) {
      const p = createParser();
      const expected = { name: 'SyntaxError', message: new RegExp(`line ${line}\\b`) };
      if (atEnd) {
        p.push(text.slice(0, cut));
        p.push('');
        p.push(text.slice(cut));
        assert.throws(() => p.end(), expected);
      } else {
        assert.throws(() => {
          p.push(text.slice(0, cut));
          p.push('');
          p.push(text.slice(cut));
        }, expected);
      }
    }
  }
});

test('header conversion preserves duplicate, special-key, and padding contracts', () => {
  const objects = parse('x,x,x_2,x,__proto__,constructor,toString,\na,b,c,d,e,f,g,h,ignored\nshort', { header: true });
  assert.deepEqual(Object.keys(objects[0]), ['x', 'x_2', 'x_2_2', 'x_3', '__proto__', 'constructor', 'toString', '']);
  assert.deepEqual(Object.values(objects[0]), ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h']);
  assert.deepEqual(Object.values(objects[1]), ['short', '', '', '', '', '', '', '']);
  assert.equal(Object.getPrototypeOf(objects[0]), Object.prototype);
  assert.deepEqual(Object.getOwnPropertyDescriptor(objects[0], '__proto__'), {
    value: 'e', enumerable: true, configurable: true, writable: true,
  });
  assert.deepEqual(parse('', { header: true }), []);
  assert.deepEqual(parse('name', { header: true }), []);
  const records = Object.freeze([Object.freeze(['v'])]);
  const header = Object.freeze(['x', 'x']);
  const options = Object.freeze({ header });
  assert.deepEqual(toObjects(records, options), [{ x: 'v', x_2: '' }]);
  assert.deepEqual(records, [['v']]);
  assert.deepEqual(header, ['x', 'x']);
  assert.deepEqual(toObjects(records, { header: [] }), [{}]);
  assert.throws(() => toObjects(records, { header: false }), TypeError);
});

