3:/**
4: * Convert string[][] records into ordinary objects without mutating any input.
5: * options.header omitted, undefined, or true: consume the first record as names;
6: * an empty input or header-only input returns []. An array header supplies the
7: * names explicitly instead, consuming no records. Other header values throw
8: * TypeError. Header entries are strings; records and options must not be null.
9: *
10: * Names are made unique left-to-right. Keep a name if unused; otherwise append
11: * '_2', '_3', ... to that original name until the first unused name is found.
12: * Example: ['x', 'x', 'x_2', 'x'] -> ['x', 'x_2', 'x_2_2', 'x_3'].
13: * An empty name is valid. All names (including '__proto__', 'constructor', and
14: * 'toString') are own enumerable writable data properties; output objects still
15: * have Object.prototype as their prototype.
16: *
17: * Pad missing cells with ''. Ignore cells beyond the number of header names.
18: * Explicit [] headers produce one empty object per input record. Never alter
19: * the records, rows, explicit header array, or options, including frozen inputs.
20: */
21:function toObjects(records, options = {}) {
22:  const header = options.header;
23:  if (header !== undefined && header !== true && !Array.isArray(header)) {
24:    throw new TypeError('header must be true or an array');
25:  }
26:  const explicit = Array.isArray(header);
27:  if (!explicit && records.length === 0) return [];
28:  const names = explicit ? header : records[0];
29:  const used = new Set();
30:  const keys = names.map(name => {
31:    let key = name;
32:    let suffix = 2;
33:    while (used.has(key)) key = `${name}_${suffix++}`;
34:    used.add(key);
35:    return key;
36:  });
37:  return records.slice(explicit ? 0 : 1).map(cells => {
38:    const object = {};
